mapper.select:
SELECT id, name
FROM genre
WHERE user_id = #{userId} AND id = #{id}

SELECT id, name
FROM genre
WHERE user_id = #{userId} AND name = #{name}

mapper.insert:
INSERT INTO figure_character (user_id, figure_id, character_id)
SELECT DISTINCT l.user_id, l.figure_id, #{fallbackId}
FROM figure_character l
WHERE l.user_id = #{userId}
  AND l.character_id IN (SELECT id FROM genre_character WHERE user_id = #{userId} AND genre_id = #{id})
  AND NOT EXISTS (
      SELECT 1 FROM figure_character o
      WHERE o.user_id = l.user_id AND o.figure_id = l.figure_id
        AND o.character_id NOT IN (SELECT id FROM genre_character WHERE user_id = #{userId} AND genre_id = #{id})
  )

mapper.delete:
DELETE FROM figure_character
WHERE user_id = #{userId}
  AND character_id IN (SELECT id FROM genre_character WHERE user_id = #{userId} AND genre_id = #{id})
